INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 1, 'theory', 'Quiz: requirements and estimates');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 0, 'Which requirement is non-functional?', '["The user can create a note", "The service responds within 200 ms in 99% of cases", "Notes can be searched by text", "The user can delete a note"]', 1, 'Non-functional requirements describe quality: latency, availability, volume, cost. The rest are features.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 1, 'A service gets 10 million daily active users with 20 actions each. Roughly how many requests per second is that on average?', '["About 20", "About 2,300", "About 200,000", "About 20 million"]', 1, '200 million requests a day divided by ~86 thousand seconds is about 2 to 3 thousand per second; for the peak, plan for 2 to 3 times more.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 2, 'Why is latency judged by p99 rather than by the mean?', '["p99 is always lower than the mean", "The mean hides rare slow requests, and users are the ones who see them", "p99 is easier to compute", "The mean cannot be computed"]', 1, 'The tail of the distribution shapes what users feel: on a page with many requests, a slow one turns up almost every time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 3, 'What happens to the availability of a chain of three components at 99.9% each?', '["It stays 99.9%", "It rises above 99.99%", "It drops to about 99.7%", "It becomes 100%"]', 2, 'Availabilities multiply: 0.999³ ≈ 0.997. That is why we add redundancy.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 1, 4, 'How do you find the bottleneck of a design?', '["Pick the most expensive component", "Calculate the utilization of each component and strengthen the most loaded one", "Add more application servers", "Increase the number of load balancers"]', 1, 'A design''s throughput is set by its most loaded link; after strengthening it you calculate again, and the bottleneck moves.');
